import{Et as e,V as t,Z as n,et as r,mt as i,nt as a,rt as o,tt as s,vt as c}from"./chunks/framework.DehstqQL.js";import"./chunks/assets.DqRdiJbZ.js";var l=JSON.parse(`{"title":"Chap14. COMPONENT COUPLING 组件耦合","description":"","frontmatter":{},"headers":[],"relativePath":"ch14.md","filePath":"ch14.md","lastUpdated":1784033199000}`),u={name:`ch14.md`};function d(t,l,u,d,f,p){let m=c(`Figures`);return i(),r(`div`,null,[l[15]||=s("",34),o(m,{figure:`14-1`},{default:e(()=>[...l[0]||=[a(`Typical component diagram`,-1)]]),_:1}),l[16]||=s("",15),o(m,{figure:`14-2`},{default:e(()=>[...l[1]||=[a(`A dependency cycle`,-1)]]),_:1}),l[17]||=s("",11),o(m,{figure:`14-3`},{default:e(()=>[...l[2]||=[a(`Inverting the dependency between Entities and Authorizer`,-1)]]),_:1}),l[18]||=n(`ol`,{start:`2`},[n(`li`,null,`Create a new component that both Entities and Authorizer depend on. Move the class(es) that they both depend on into that new component (Figure 14.4).`)],-1),l[19]||=n(`blockquote`,null,[n(`ol`,{start:`2`},[n(`li`,null,`创建一个新的组件，并让 Entities 与 Authorize 这两个组件都依赖于它。将现有的这两个组件中互相依赖的类全部放入新组件（如图 14.4 所示）。`)])],-1),o(m,{figure:`14-4`},{default:e(()=>[...l[3]||=[a(`The new component that both Entities and Authorizer depend on`,-1)]]),_:1}),l[20]||=s("",36),o(m,{figure:`14-5`},{default:e(()=>[...l[4]||=[a(`X: a stable component`,-1)]]),_:1}),l[21]||=n(`p`,null,`Figure 14.6 shows Y, which is a very unstable component. No other components depend on Y, so we say that it is irresponsible. Y also has three components that it depends on, so changes may come from three external sources. We say that Y is dependent.`,-1),l[22]||=n(`blockquote`,null,[n(`p`,null,`下面再来看看图 14.6 中的 Y 组件，这是一个非常不稳定的组件。由于没有其他的组件依赖 Y，所以 Y 并不对任何组件负责。但因为 Y 同时依赖于三个组件，所以它的变更就可能由三个不同的源产生。这里就说 Y 是有依赖性的组件。`)],-1),o(m,{figure:`14-6`},{default:e(()=>[...l[5]||=[a(`Y: a very unstable component`,-1)]]),_:1}),l[23]||=s("",8),o(m,{figure:`14-7`},{default:e(()=>[...l[6]||=[a(`Our example`,-1)]]),_:1}),l[24]||=s("",15),o(m,{figure:`14-8`},{default:e(()=>[...l[7]||=[a(`An ideal configuration for a system with three components`,-1)]]),_:1}),l[25]||=n(`p`,null,`The diagram in Figure 14.9 shows how the SDP can be violated.`,-1),l[26]||=n(`blockquote`,null,[n(`p`,null,`下面再通过图 14.9 来看看违反 SDP 的情况：`)],-1),o(m,{figure:`14-9`},{default:e(()=>[...l[8]||=[a(`SDP violation`,-1)]]),_:1}),l[27]||=n(`p`,null,`Flexible is a component that we have designed to be easy to change. We want Flexible to be unstable. However, some developer, working in the component named Stable, has hung a dependency on Flexible. This violates the SDP because the I metric for Stable is much smaller than the I metric for Flexible. As a result, Flexible will no longer be easy to change. A change to Flexible will force us to deal with Stable and all its dependents.`,-1),l[28]||=n(`blockquote`,null,[n(`p`,null,`在图 14.9 中，Flexible 是在设计中要确保其易于变更的组件，因此我们会希望 Flexible 是不稳定的。然而，Stable 组件的开发人员却引入了对 Flexible 组件的依赖。这种情况就违反了 SDP，因为 Stable 组件的 I 指标要远小于 Flexible 的 I 指标。这将导致 Flexible 组件的变更难度大大增加，因为对 Flexible 组件的任何修改都必须要考虑 Stable 组件及该组件自身存在的依赖关系。`)],-1),l[29]||=n(`p`,null,`To fix this problem, we somehow have to break the dependence of Stable on Flexible. Why does this dependency exist? Let’s assume that there is a class C within Flexible that another class U within Stable needs to use (Figure 14.10).`,-1),l[30]||=n(`blockquote`,null,[n(`p`,null,`如果想要修复这个问题，就必须要将 stable 与 Flexible 这两个组件之间的依赖关系打破。为此，我们就需要了解这个依赖关系到底为什么会存在，这里假设是因为 Stable 组件中的某个类 U 需要使用 Flexible 组件中的一个类 C，如图 14.10 所示：`)],-1),o(m,{figure:`14-10`},{default:e(()=>[...l[9]||=[a(`U within Stable uses C within Flexible`,-1)]]),_:1}),l[31]||=n(`p`,null,`We can fix this by employing the DIP. We create an interface class called US and put it in a component named UServer. We make sure that this interface declares all the methods that U needs to use. We then make C implement this interface as shown in Figure 14.11. This breaks the dependency of Stable on Flexible, and forces both components to depend on UServer. UServer is very stable (I = 0), and Flexible retains its necessary instability (I = 1). All the dependencies now flow in the direction of decreasing I.`,-1),l[32]||=n(`blockquote`,null,[n(`p`,null,`我们可以利用 DIP 来修复这个问题。具体来说就是创造一个 UServer 组件，并在其中设置一个 US 接口类。然后，确保这个接口类中包含了所有 U 需要使用的函数，再让 C 实现这个接口，如图 14.11 所示。这样一来，我们就将从 Stable 到 Flexible 的这条依赖关系打破了，强迫这两个组件都依赖于 UServer。现在，UServer 组件会是非常稳定的（I=0），而 Flexibile 组件则会依然保持不稳定的状态（I=1），结构图中所有的依赖关系都流向 I 递减的方向了。`)],-1),o(m,{figure:`14-11`},{default:e(()=>[...l[10]||=[a(`C implements the interface class US`,-1)]]),_:1}),l[33]||=s("",33),o(m,{figure:`14-12`},{default:e(()=>[...l[11]||=[a(`The I/A graph`,-1)]]),_:1}),l[34]||=n(`p`,null,`Not all components fall into one of these two positions, because components often have degrees of abstraction and stability. For example, it is very common for one abstract class to derive from another abstract class. The derivative is an abstraction that has a dependency. Thus, though it is maximally abstract, it will not be maximally stable. Its dependency will decrease its stability.`,-1),l[35]||=n(`blockquote`,null,[n(`p`,null,`当然，不可能所有的组件都能处于这两个位置上，因为组件通常都有各自的稳定程度和抽象化程度。例如一个抽象类有时会衍生于另一个抽象类，这种情况是很常见的，而这个衍生过程就意味着某种依赖关系的产生。因此，虽然该组件是全抽象的，但它并不是完全稳定的，上述依赖关系降低了它的稳定程度。`)],-1),l[36]||=n(`p`,null,`Since we cannot enforce a rule that all components sit at either (0, 1) or (1, 0), we must assume that there is a locus of points on the A/I graph that defines reasonable positions for components. We can infer what that locus is by finding the areas where components should not be—in other words, by determining the zones of exclusion (Figure 14.13).`,-1),l[37]||=n(`blockquote`,null,[n(`p`,null,`既然不能强制要求所有的组件都处于(0,1)和(1,0)这两个位置上，那么就必须假设 A/I 图上存在着一个合理组件的区间。而这个区间应该可以通过排除法推导出来，也就是说，我们可以先找出那些组件不应该处于的位置（请参考图 14.13）：`)],-1),o(m,{figure:`14-13`},{default:e(()=>[...l[12]||=[a(`Zones of exclusion`,-1)]]),_:1}),l[38]||=s("",34),o(m,{figure:`14-14`},{default:e(()=>[...l[13]||=[a(`Scatterplot of the components`,-1)]]),_:1}),l[39]||=n(`p`,null,`Another way to use the metrics is to plot the D metric of each component over time. The graph in Figure 14.15 is a mock-up of such a plot. You can see that some strange dependencies have been creeping into the Payroll component over the last few releases. The plot shows a control threshold at D = 0.1. The R2.1 point has exceeded this control limit, so it would be worth our while to find out why this component is so far from the main sequence.`,-1),l[40]||=n(`blockquote`,null,[n(`p`,null,`D 指标的另外一种用法是按时间来跟踪每个组件的值，下面用图 14.15 来做一个示范。在该图中可以看到，Payroll 组件在最近几次发布中累积了一些意外的对外依赖。图中的 Q=0.1 是组件的达标红线，R2.1 这个值已经超出了红线范围，这就告诉我们现在值得花一些精力来找出这个组件偏离主序列线的原因了。`)],-1),o(m,{figure:`14-15`},{default:e(()=>[...l[14]||=[a(`Plot of D for a single component over time`,-1)]]),_:1}),l[41]||=n(`h2`,{id:`conclusion-本章小结`,tabindex:`-1`},[a(`CONCLUSION 本章小结 `),n(`a`,{class:`header-anchor`,href:`#conclusion-本章小结`,"aria-label":`Permalink to “CONCLUSION 本章小结”`},`​`)],-1),l[42]||=n(`p`,null,`The dependency management metrics described in this chapter measure the conformance of a design to a pattern of dependency and abstraction that I think is a “good” pattern. Experience has shown that certain dependencies are good and others are bad. This pattern reflects that experience. However, a metric is not a god; it is merely a measurement against an arbitrary standard. These metrics are imperfect, at best, but it is my hope that you find them useful.`,-1),l[43]||=n(`blockquote`,null,[n(`p`,null,`本章介绍了各种可用于依赖关系管理的指标，它们可以被用来里化分析某个系统设计与“优秀”设计模式之间的契合度。根据以往的经验，组件之间有些依赖关系是好的，有些依赖关系则是不好的，这些经验最后都会体现在这个设计模式中。当然，指标并不等同于真理，它只是对我们所定义标准的一个衡量。这些指标肯定是不完美的，但是我希望它们对读者有价值。`)],-1)])}var f=t(u,[[`render`,d]]);export{l as __pageData,f as default};